(* [comment removed for export] *)
Definition CNT (c : Z) (S : list Z) : Z :=
  if c =? 63 then zcount (fun n => MMAP_THRESHOLD <=? n) S
  else zcount (fun n => negb (MMAP_THRESHOLD <=? n) && (size_to_class n =? c)) S.

